-- Additive private production DDL for root review. Not applied by this QA task.
-- SQLite equivalent was generated by drizzle-kit as 0007_chat_reactions.sql.
CREATE TABLE brigade.chat_reactions (
  message_id text NOT NULL REFERENCES brigade.chat_messages(id) ON DELETE CASCADE,
  user_id text NOT NULL REFERENCES brigade.profiles(id) ON DELETE CASCADE,
  emoji text NOT NULL,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY (message_id,user_id),
  CONSTRAINT chat_reactions_emoji CHECK (emoji IN ('👍','❤️','🔥','👏','👀','✅'))
);
CREATE INDEX chat_reactions_message_emoji ON brigade.chat_reactions(message_id,emoji);
ALTER TABLE brigade.chat_reactions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON brigade.chat_reactions FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON brigade.chat_reactions TO service_role;

